export const REQUIRED_LOCALE_KEYS=["ENDLESS SURVIVAL PROTOCOL","ENDLESS · OFFLINE READY","One core. Infinite void. Don't stop moving.","STARTING LOADOUTS","CHOOSE YOUR COMBAT STYLE","Balanced · reliable fire","Guarding shard · close control","Critical sparks · chained hits","Loadouts are starting bonuses, not permanent power. Every style has trade-offs.","OPTIONAL CHALLENGES","PLAY YOUR WAY","No objective · play at your own pace","Collect 180 scrap · +2 Core","Defeat an Elite · +3 Core","12 storm kills · +2 Core","Compare your best run with every pilot","Optional · sync your profile and publish scores","AUTO-FIRE ENABLED · SCRAP CORE PERSISTS BETWEEN RUNS","FIELD GUIDE · FIRST RUN","HOME","BATTLE","GALAXY","RANKINGS","SKIN SHOP","CAREER","SETTINGS","Pilot profile and quick start. Daily status is planned for a later update.","Solo is playable. Co-op and Ranked stay unavailable until trusted server infrastructure is ready.","View region progress. A dedicated sector and boss browser is planned.","Open the current shared leaderboard. Global, Türkiye and Friends filters are planned.","Open country flags, special banners and the cosmetic collection.","Open your pilot profile, current statistics and achievements.","Open audio, controls and accessibility settings.","LANGUAGE","WELCOME, PILOT.","Choose your language to begin your journey. You can change it anytime in Settings.","Your choice is saved on this device."];


export function translateText(key){const lang=(()=>{try{return localStorage.getItem("cosmic-scrap-language")||"en"}catch{return"en"}})();return translations[lang]?.[key]||translations.en?.[key]||key}
function language(){try{const saved=localStorage.getItem("cosmic-scrap-language");return localeMeta.some(item=>item.code===saved)?saved:"en"}catch{return"en"}}
function replaceText(el,value){if(!el)return;const node=[...el.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(node)node.textContent=value;else el.insertBefore(document.createTextNode(value),el.firstChild)}
function applyLanguage(lang=language()){
 const dict=translations[lang]||translations.en;document.documentElement.lang=lang;
 for(const el of document.querySelectorAll("button,label,strong,small,span,p,h1,h2,h3,kbd,option")){for(const node of el.childNodes){if(node.nodeType!==Node.TEXT_NODE||!node.textContent.trim())continue;if(node.__csEnglish===undefined)node.__csEnglish=node.textContent;const original=node.__csEnglish.trim();node.textContent=lang==="en"?node.__csEnglish:(dict[original]||node.__csEnglish)}}
 const btn=document.getElementById("language-toggle");if(btn){const selectedLocale=localeMeta.find(item=>item.code===lang)||localeMeta[0];btn.textContent=selectedLocale.flag+" "+selectedLocale.code;btn.setAttribute("aria-label","Language: "+selectedLocale.label)}const languageSelect=document.getElementById("setting-language");if(languageSelect)languageSelect.value=lang;const homeLanguageSelect=document.getElementById("home-language-select");if(homeLanguageSelect)homeLanguageSelect.value=lang;
 const placeholders={"pilot@example.com":["pilot@example.com","pilot@ornek.com"],"At least 8 characters":["At least 8 characters","En az 8 karakter"],"Exact pilot username":["Exact pilot username","Tam oyuncu kullanıcı adı"],"8-character invite code":["8-character invite code","8 karakterli davet kodu"],"Write a respectful message…":["Write a respectful message…","Saygılı bir mesaj yaz…"]};document.querySelectorAll("input,textarea").forEach(el=>{const p=el.dataset.csEnPlaceholder||(el.dataset.csEnPlaceholder=el.placeholder);if(placeholders[p])el.placeholder=placeholders[p][lang==="tr"?1:0]});
 document.querySelectorAll("[data-i18n-en][data-i18n-tr]").forEach(el=>{const english=el.dataset.i18nEn;replaceText(el,dict[english]||(lang==="tr"?el.dataset.i18nTr:english))});
 document.querySelectorAll("[data-contract]").forEach(b=>{const keys={none:["ENDLESS SURVIVAL","No objective · play at your own pace"],salvager:["SALVAGE RUN","Collect 180 scrap · +2 Core"],elite:["ELITE HUNTER","Defeat an Elite · +3 Core"],storm:["STORMBREAKER","12 storm kills · +2 Core"]}[b.dataset.contract];if(!keys)return;const strong=b.querySelector("strong"),small=b.querySelector("small");if(strong)strong.textContent=dict[keys[0]]||keys[0];if(small)small.textContent=dict[keys[1]]||keys[1]});
 document.querySelectorAll("[data-skin]").forEach(b=>{const names={blue:"NEBULA",mint:"PHOTON",violet:"RIFT",amber:"SOLAR",red:"PHOENIX",gold:"SUPERNOVA"};const name=names[b.dataset.skin];const label=b.querySelector("span");if(label&&name)label.textContent=dict[name]||name});
 window.dispatchEvent(new Event("cosmic-scrap:language-changed"));
}
if(typeof document!=="undefined"){
 const cycleLanguage=()=>{const order=localeMeta.map(item=>item.code),next=order[(order.indexOf(language())+1)%order.length];try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)};
 document.getElementById("language-toggle")?.addEventListener("click",cycleLanguage);
 document.getElementById("setting-language")?.addEventListener("change",event=>{const next=localeMeta.some(item=>item.code===event.target.value)?event.target.value:"en";try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)});document.getElementById("home-language-select")?.addEventListener("change",event=>{const next=localeMeta.some(item=>item.code===event.target.value)?event.target.value:"en";try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)});
 applyLanguage();
 if(!localStorage.getItem("cosmic-scrap-language-selected")){const modal=document.createElement("section");modal.id="language-welcome";modal.className="language-welcome";modal.setAttribute("role","dialog");modal.setAttribute("aria-modal","true");modal.innerHTML='<div class="language-welcome-card"><span class="language-welcome-kicker">TAVIRO · INDEPENDENT GAME</span><div class="language-welcome-emblem">✦</div><h2>WELCOME, PILOT.</h2><p>Choose your language to begin your journey. You can change it anytime in Settings.</p><div class="language-welcome-grid"></div><small>Your choice is saved on this device.</small></div>';const grid=modal.querySelector(".language-welcome-grid");localeMeta.forEach(item=>{const b=document.createElement("button");b.type="button";b.className="language-welcome-option";b.innerHTML='<span class="language-welcome-flag"></span><span class="language-welcome-name"></span><span class="language-welcome-code"></span>';b.querySelector(".language-welcome-flag").textContent=item.flag;b.querySelector(".language-welcome-name").textContent=item.label;b.querySelector(".language-welcome-code").textContent=item.code;b.addEventListener("click",()=>{localStorage.setItem("cosmic-scrap-language",item.code);localStorage.setItem("cosmic-scrap-language-selected","1");applyLanguage(item.code);modal.remove()});grid.append(b)});document.body.append(modal);applyLanguage(language());grid.querySelector("button")?.focus();}
}


